'use strict';
/**
 * wx-server-sdk 本地 mock（仅 B2 端到端模拟用，不属于工程代码）
 * 支持用到的 API：init / getWXContext / database()
 *   db.collection(name).add({data}) / .where(q).limit(n).get() / .where(q).get()
 *   db.collection(name).doc(id).get() / .doc(id).update({data})
 *   db.command.in(arr)
 * 内存存储，进程生命周期内有效。
 */
const DYNAMIC_CURRENT_ENV = Symbol('DYNAMIC_CURRENT_ENV');
const store = {};

function coll(name) {
  if (!store[name]) store[name] = { docs: [], seq: 0 };
  return store[name];
}

function match(doc, q) {
  for (const k of Object.keys(q)) {
    const v = q[k];
    if (v && typeof v === 'object' && v.__cmd === 'in') {
      if (!v.arr.includes(doc[k])) return false;
    } else if (doc[k] !== v) return false;
  }
  return true;
}

function makeDb() {
  return {
    command: { in: (arr) => ({ __cmd: 'in', arr: arr }) },
    // 模拟建集合：mock 中集合按需自动生成，恒成功
    createCollection: async (name) => {
      coll(name);
      return { errCode: 0 };
    },
    collection: (name) => {
      const c = coll(name);
      return {
        add: async ({ data }) => {
          const _id = name + '_' + (++c.seq) + '_' + Date.now().toString(36);
          // 模拟云开发行为：云函数写入自动注入调用方 _openid
          const doc = Object.assign({}, data);
          if (!doc._openid) doc._openid = process.env.MOCK_OPENID || 'openid_default';
          c.docs.push(Object.assign(doc, { _id: _id }));
          return { _id: _id };
        },
        where: (q) => {
          const builder = {
            limit: () => builder,
            orderBy: () => builder,
            skip: () => builder,
            field: () => builder,
            get: async () => ({ data: c.docs.filter((d) => match(d, q)) }),
            count: async () => ({ total: c.docs.filter((d) => match(d, q)).length }),
            update: async ({ data }) => {
              let n = 0;
              for (const d of c.docs) {
                if (match(d, q)) { Object.assign(d, data); n++; }
              }
              return { stats: { updated: n } };
            },
            remove: async () => {
              const before = c.docs.length;
              c.docs = c.docs.filter((d) => !match(d, q));
              return { stats: { removed: before - c.docs.length } };
            }
          };
          return builder;
        },
        doc: (id) => ({
          get: async () => {
            const d = c.docs.find((x) => x._id === id);
            return { data: d || null };
          },
          update: async ({ data }) => {
            const d = c.docs.find((x) => x._id === id);
            if (d) Object.assign(d, data);
            return { stats: { updated: d ? 1 : 0 } };
          }
        })
      };
    }
  };
}

module.exports = {
  DYNAMIC_CURRENT_ENV: DYNAMIC_CURRENT_ENV,
  init: () => {},
  getWXContext: () => ({ OPENID: process.env.MOCK_OPENID || 'openid_default' }),
  database: () => makeDb(),
  __store: store
};
